def prodclock2(code):
    csum=code[:,:8]; ssum=code[:,8:]; idx={m:k for k,m in enumerate(MS8)}
    cs=[];ss=[]
    for m in MS4:
        h=(2*m)%112
        cc,sc = (csum[:,idx[h]],ssum[:,idx[h]]) if h<=56 else (csum[:,idx[112-h]],-ssum[:,idx[112-h]])
        cs.append(0.5*(csum[:,idx[m]]**2-ssum[:,idx[m]]**2)-0.5*cc)
        ss.append(csum[:,idx[m]]*ssum[:,idx[m]]-0.5*sc)
    return np.hstack([np.stack(cs,1),np.stack(ss,1)])
